command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "5eb0fbb50c627a736e8e6ca2bb4d9793ebad33ea") { throw "main moved" }
$remote = git ls-remote --heads origin work/large-folder-resident-window
if ($LASTEXITCODE -ne 0) { throw "list work branch failed" }
if ($remote -match "refs/heads/work/large-folder-resident-window") {
  git push origin --delete work/large-folder-resident-window
  if ($LASTEXITCODE -ne 0) { throw "work branch cleanup failed" }
}
git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "main fast-forward failed" }
Write-Host "RESIDENT_WINDOW_WORK_BRANCH_CLEANUP_PASS"
